class PagerModel {
    var totalPages: Int = 0

    func updateTotalPages(data: [Any], itemsPerPage: Int) {
        let totalItems = data.count
        totalPages = totalItems / itemsPerPage
        if totalItems % itemsPerPage != 0 {
            totalPages += 1
        }
    }
}
