use Carbon\Carbon;
use Illuminate\Database\Eloquent\Collection;

class CustomDateCollection extends Collection
{
    public function filterFutureDates(): CustomDateCollection
    {
        $filteredDates = $this->filter(function (Carbon $date) {
            return $date->isFuture();
        });

        return new CustomDateCollection($filteredDates->all());
    }

    public function filterPastDates(): CustomDateCollection
    {
        $filteredDates = $this->filter(function (Carbon $date) {
            return $date->isPast();
        });

        return new CustomDateCollection($filteredDates->all());
    }

    public function addDaysToDates(int $days): CustomDateCollection
    {
        $modifiedDates = $this->map(function (Carbon $date) use ($days) {
            return $date->copy()->addDays($days);
        });

        return new CustomDateCollection($modifiedDates->all());
    }
}
```

