class FatalError(Exception):
    pass

def handle_redirects(initial_url: str) -> str:
    rdseq = [initial_url]  # Initialize the redirect sequence with the initial URL
    max_redirects = 8  # Maximum allowed redirects

    while True:
        # Perform the HTTP request to the current URL
        http_response = perform_http_request(rdseq[-1])  # Assuming a function perform_http_request exists

        # Log the HTTP status code and the location of the redirect
        logger.info("HTTP %d Location: %s" % (http_response.status_code, http_response.headers["location"]))

        # Check if the status code indicates a redirect
        if http_response.status_code in [300, 301, 302]:
            url = http_response.headers["location"]
            if url in rdseq:
                raise FatalError("Loop detected in redirects")
            else:
                rdseq.append(url)
                if len(rdseq) > max_redirects:
                    raise FatalError("Too long sequence of redirects: %s" % rdseq)
        else:
            # Return the final URL after following the redirects
            return rdseq[-1]
```

