import javax.validation.ConstraintViolation;
import javax.validation.Validation;
import javax.validation.Validator;
import javax.validation.ValidatorFactory;
import java.util.Set;

public class CountryValidator {

    public boolean validateCountryDto(CountryDto countryDto) {
        ValidatorFactory factory = Validation.buildDefaultValidatorFactory();
        Validator validator = factory.getValidator();

        Set<ConstraintViolation<CountryDto>> violations = validator.validate(countryDto);

        for (ConstraintViolation<CountryDto> violation : violations) {
            if (violation.getPropertyPath().toString().equals("id") && violation.getInvalidValue() == null) {
                return false; // id field must not be null
            }
            if (violation.getPropertyPath().toString().equals("name") && violation.getInvalidValue() != null
                    && violation.getInvalidValue().toString().length() > 100) {
                return false; // name field must not exceed 100 characters if not null
            }
        }

        return true; // CountryDto is valid
    }
}
```

In the solution, the `validateCountryDto` method uses the Java Bean Validation API to perform the validation based on the annotations present in the `CountryDto` class. It creates a validator instance and checks for any constraint violations. If any violation is found for the `id` or `name` fields, the method returns `false`, indicating that the `CountryDto` object is not valid. Otherwise, it returns `true` to signify that the object is valid.

