def parse_config_file(config_file_path: str) -> dict:
    with open(config_file_path, 'r') as file:
        lines = file.readlines()

    config_dict = {}
    current_rule = None
    for line in lines:
        line = line.strip()
        if line.startswith('[') and line.endswith(']'):
            current_rule = line[1:-1]
            config_dict[current_rule] = {}
        elif line.startswith('function'):
            function_name = line.split('=')[1].strip().strip('"')
            config_dict[current_rule]['function'] = function_name
        elif line.startswith('parameters'):
            parameters = line.split('=')[1].strip()
            if parameters:
                param_dict = eval(parameters)
                config_dict[current_rule]['parameters'] = param_dict
            else:
                config_dict[current_rule]['parameters'] = {}

    return config_dict
```

