func handleTokenResponse(result: Result<(accessToken: String, expiresIn: TimeInterval), Error>, completion: @escaping (Result<Void, BoxAPIAuthError>) -> Void) {
    switch result {
    case let .success(accessToken, expiresIn):
        if expiresIn < self.configuration.tokenRefreshThreshold {
            // Trigger token refresh process
            self.refreshToken { refreshResult in
                switch refreshResult {
                case .success(let newAccessToken, let newExpiresIn):
                    let tokenInfo = TokenInfo(accessToken: newAccessToken, expiresIn: newExpiresIn)
                    self.tokenInfo = tokenInfo
                    self.tokenStore.write(tokenInfo: tokenInfo) { storeResult in
                        completion(storeResult.mapError { BoxAPIAuthError(message: .storageError($0.localizedDescription)) })
                    }
                case .failure(let error):
                    completion(.failure(BoxAPIAuthError(message: .tokenRefreshError(error.localizedDescription))))
                }
            }
        } else {
            let tokenInfo = TokenInfo(accessToken: accessToken, expiresIn: expiresIn)
            self.tokenInfo = tokenInfo
            self.tokenStore.write(tokenInfo: tokenInfo) { storeResult in
                completion(storeResult.mapError { BoxAPIAuthError(message: .storageError($0.localizedDescription)) })
            }
        }
    case let .failure(error):
        completion(.failure(BoxAPIAuthError(message: .tokenResponseError(error.localizedDescription))))
    }
}
