 *
 * @param string $fileName The name of the file to be pushed to the user
 */
function pushFileToUser($fileName) {
    $filePath = FILE_PATH . $fileName;

    if (file_exists($filePath) && is_readable($filePath)) {
        // Set appropriate headers
        header('Content-Description: File Transfer');
        header('Content-Type: application/octet-stream');
        header('Content-Disposition: attachment; filename="' . basename($filePath) . '"');
        header('Expires: 0');
        header('Cache-Control: must-revalidate');
        header('Pragma: public');
        header('Content-Length: ' . filesize($filePath));

        // Flush the output buffer
        ob_clean();
        flush();

        // Read and output the file contents
        readfile($filePath);
        exit;
    } else {
        // Handle file not found or inaccessible
        header("HTTP/1.0 404 Not Found");
        echo "File not found or inaccessible";
        exit;
    }
}

// Example usage
$requestedFile = 'example_file.pdf';
pushFileToUser($requestedFile);
