function calculateTotalArea(rectangles: { x1: number, y1: number, x2: number, y2: number }[]): number {
  let totalArea = 0;

  for (let i = 0; i < rectangles.length; i++) {
    const rect1 = rectangles[i];
    totalArea += (rect1.x2 - rect1.x1) * (rect1.y2 - rect1.y1);

    for (let j = i + 1; j < rectangles.length; j++) {
      const rect2 = rectangles[j];
      const xOverlap = Math.max(0, Math.min(rect1.x2, rect2.x2) - Math.max(rect1.x1, rect2.x1));
      const yOverlap = Math.max(0, Math.min(rect1.y2, rect2.y2) - Math.max(rect1.y1, rect2.y1));
      const overlapArea = xOverlap * yOverlap;
      totalArea -= overlapArea;
    }
  }

  return totalArea;
}
```

This solution iterates through each rectangle, adding its area to the total area, and then subtracts the overlapping areas between pairs of rectangles. The final result is the total non-overlapping area of all rectangles.

