def countSubarrays(nums):
    def getCount(length):
        return (length - 1) * length // 2

    total_count = 0
    curr_diff = nums[1] - nums[0]
    left = 0

    for i in range(2, len(nums)):
        if nums[i] - nums[i - 1] != curr_diff:
            total_count += getCount(i - left)
            left = i - 1
            curr_diff = nums[i] - nums[i - 1]

