        guard index >= 0, index < subsections.count else { return }
        subsections.remove(at: index)
    }

    func subsectionsNamed(_ name: String) -> [Section] {
        var result: [Section] = []
        for section in subsections {
            if section.name == name {
                result.append(section)
            }
            result += section.subsectionsNamed(name)
        }
        return result
    }
}
