def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def rotate_number(n):
    n_str = str(n)
    rotations = [int(n_str[i:] + n_str[:i]) for i in range(len(n_str))]
    return rotations

def count_circular_primes(limit):
    circular_primes = set()
    for num in range(2, limit):
        if all(digit in '1379' for digit in str(num)):
            rotations = rotate_number(num)
            if all(is_prime(rotated) for rotated in rotations):
                circular_primes.update(rotations)
    return len(circular_primes)

limit = 1000000
print(count_circular_primes(limit))  # Output: 55
```

The `is_prime` function checks if a number is prime. The `rotate_number` function generates all the rotations of a number. The `count_circular_primes` function iterates through numbers below the given limit, checks if they are circular primes, and returns the count of circular primes. The example provided calculates the count of circular primes below one million.

