public class EventDispatcher
{
    private readonly Dictionary<string, List<Delegate>> eventHandlers = new Dictionary<string, List<Delegate>>();

    public void AddEventHandler(string eventName, Delegate eventHandler)
    {
        if (!eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName] = new List<Delegate>();
        }
        eventHandlers[eventName].Add(eventHandler);
    }

    public void RemoveEventHandler(string eventName, Delegate eventHandler)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName].Remove(eventHandler);
        }
    }

    public void TriggerEvent(string eventName, object eventData)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            foreach (var handler in eventHandlers[eventName])
            {
                handler.DynamicInvoke(this, new CustomEventArgs(eventData));
            }
        }
    }
}
```

