import numpy as np

class AutonomousVehicleController:
    def __init__(self, t, amplitude_pos, amplitude_neg):
        self.t = t
        self.amplitude_pos = amplitude_pos
        self.amplitude_neg = amplitude_neg
        self.steering = 0.0
        self.throttle = 0.0

    def calculate_control(self, s_off, throttle):
        if self.t <= 180:
            s_off *= self.amplitude_pos
        else:
            s_off *= self.amplitude_neg
        self.steering += s_off

        self.steering /= 128.0
        self.throttle /= 128.0

        return np.clip(self.steering, -1.0, 1.0), np.clip(self.throttle, -1.0, 1.0)
