[AttributeUsage(AttributeTargets.Class, AllowMultiple = false)]
public class AutoMapToAttribute : Attribute
{
    private Type _targetType;

    public AutoMapToAttribute(Type targetType)
    {
        _targetType = targetType;
    }

    public void MapProperties(object source, object destination)
    {
        var sourceProperties = source.GetType().GetProperties();
        var destinationProperties = _targetType.GetProperties();

        foreach (var sourceProperty in sourceProperties)
        {
            var destinationProperty = destinationProperties.FirstOrDefault(p => p.Name == sourceProperty.Name && p.PropertyType == sourceProperty.PropertyType);
            if (destinationProperty != null)
            {
                var value = sourceProperty.GetValue(source);
                destinationProperty.SetValue(destination, value);
            }
        }
    }
}

// Example usage of AutoMapTo attribute
[AutoMapTo(typeof(ProjectTask))]
public class TaskViewModel
{
    public int Id { get; set; }
    public string Title { get; set; }
    public string Description { get; set; }
