class Graph:
    def __init__(self):
        self.__adjacency_list = {}

    def add_node(self, node):
        if node not in self.__adjacency_list:
            self.__adjacency_list[node] = []

    def add_edge(self, node1, node2):
        if node1 in self.__adjacency_list and node2 in self.__adjacency_list:
            self.__adjacency_list[node1].append(node2)
            self.__adjacency_list[node2].append(node1)

    def get_nodes(self):
        return list(self.__adjacency_list.keys())

    def get_edges(self):
        edges = []
        for node, neighbors in self.__adjacency_list.items():
            for neighbor in neighbors:
                if (neighbor, node) not in edges:
                    edges.append((node, neighbor))
        return edges
```
