// Define the interface for ConfirmModalProps
interface ConfirmModalProps {
  open: boolean;
  onRequestClose: () => void;
  onConfirm?: () => void;
  onCancel?: () => void;
  confirmButton?: boolean;
  cancelButton?: boolean;
  cancelOnBackgroundPress?: boolean;
}

