const ConfirmModal: React.FC<ConfirmModalProps> = ({
  open,
  onRequestClose,
  onConfirm,
  onCancel,
  confirmButton = true,
  cancelButton = true,
  cancelOnBackgroundPress = true,
  children,
}) => {
  const handleConfirm = () => {
    if (onConfirm) {
      onConfirm();
    }
    onRequestClose();
  };

  const handleCancel = () => {
    if (onCancel) {
      onCancel();
    }
    onRequestClose();
  };

  const handleBackgroundClick = () => {
    if (cancelOnBackgroundPress) {
      onRequestClose();
    }
  };

  return open ? (
    <div className="modal" onClick={handleBackgroundClick}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        {children}
        {confirmButton && <button onClick={handleConfirm}>Confirm</button>}
        {cancelButton && <button onClick={handleCancel}>Cancel</button>}
      </div>
    </div>
  ) : null;
};
