class MemoryBlock:
    def __init__(self, start_address, size):
        self.start_address = start_address
        self.size = size

class Process:
    def __init__(self, name, size):
        self.name = name
        self.size = size

def best_fit_allocation(free_blocks, processes):
    allocation_status = []

    for process in processes:
        best_fit_block = None
        for block in free_blocks:
            if block.size >= process.size:
                if best_fit_block is None or block.size < best_fit_block.size:
                    best_fit_block = block

        if best_fit_block is not None:
            allocation_status.append((process.name, best_fit_block.start_address))
            best_fit_block.start_address += process.size
            best_fit_block.size -= process.size
        else:
            allocation_status.append((process.name, "Not Allocated"))

    return allocation_status

# Test the best_fit_allocation function
