    value: string;
    depth: number;
    width: number;
    left: Node | null;
    right: Node | null;

    constructor(value: string) {
        this.value = value;
        this.depth = 0;
        this.width = 0;
        this.left = null;
        this.right = null;
    }

    getNodesAtDepth(depth: number): Array<Node> {
        // Implementation not shown
    }
}
