fn part1(digits: &[u32]) -> u32 {
    captcha(digits, 1)
}

fn part2(digits: &[u32]) -> u32 {
    captcha(digits, digits.len() / 2)
}

fn parse_input(s: &str) -> Vec<u32> {
    s.chars().flat_map(|x| x.to_digit(10)).collect()
}

fn captcha(digits: &[u32], offset: usize) -> u32 {
    let lookahead = digits.iter().cycle().skip(offset);
    let sum: u32 = digits.iter()
        .zip(lookahead)
        .filter(|&(a, b)| a == b)
        .map(|(a, _)| a)
        .sum();
    sum
}

fn main() {
    let input = "91212129";
    let digits = parse_input(input);
    println!("Part 1: {}", part1(&digits));  // Output: 9
    println!("Part 2: {}", part2(&digits));  // Output: 6
}
```

