use crate::db::Database;
use std::sync::{Arc, Mutex};
use hyper::{Body, Request, Response, Server, Method, StatusCode};
use hyper::rt::Future;
use hyper::service::service_fn_ok;

pub fn get_handler(req: Request<Body>, db: Arc<Mutex<Database>>) -> Response<Body> {
    // Extract key from request
    let key = req.uri().path().trim_start_matches('/');

    // Access the database
    let data = db.lock().unwrap();
    match data.get(key) {
        Some(value) => Response::new(Body::from(value.clone())),
        None => Response::builder()
            .status(StatusCode::NOT_FOUND)
            .body(Body::empty())
            .unwrap(),
    }
}

pub fn set_handler(req: Request<Body>, db: Arc<Mutex<Database>>) -> Response<Body> {
    // Extract key and value from request
    let (key, value) = {
        let parts = req.uri().path().trim_start_matches('/').split('=').collect::<Vec<&str>>();
        (parts[0].to_string(), parts[1].to_string())
    };

    // Access the database
    let mut data = db.lock().unwrap();
    data.set(key, value);
    Response::new(Body::from("Value set successfully"))
}

pub fn delete_handler(req: Request<Body>, db: Arc<Mutex<Database>>) -> Response<Body> {
    // Extract key from request
    let key = req.uri().path().trim_start_matches('/');

    // Access the database
    let mut data = db.lock().unwrap();
    match data.delete(key) {
        Some(_) => Response::new(Body::from("Value deleted successfully")),
        None => Response::builder()
            .status(StatusCode::NOT_FOUND)
            .body(Body::empty())
            .unwrap(),
    }
}

// main.rs
use hyper::service::service_fn;
use hyper::{Body, Request, Response, Server, Method, StatusCode};
use std::sync::{Arc, Mutex};

mod db;
mod handlers;

use db::*;
use handlers::*;

fn main() {
    let addr = ([127, 0, 0, 1], 3000).into();
    let db = Arc::new(Mutex::new(Database::new()));

    let new_svc = move || {
        let db = db.clone();
        service_fn(move |req| match (req.method(), req.uri().path()) {
            (&Method::GET, "/get") => Ok(get_handler(req, db.clone())),
            (&Method::POST, "/set") => Ok(set_handler(req, db.clone())),
            (&Method::DELETE, "/delete") => Ok(delete_handler(req, db.clone())),
            _ => {
                let response = Response::builder()
                    .status(StatusCode::NOT_FOUND)
                    .body(Body::empty())
                    .unwrap();
                Ok(response)
            }
        })
    };

    let server = Server::bind(&addr)
        .serve(new_svc)
        .map_err(|e| eprintln!("server error: {}", e));

    hyper::rt::run(server);
}
