def power(a: float, n: int) -> float:
    if n == 0:
        return 1
    if n < 0:
        a = 1 / a
        n = -n
    result = 1
    while n > 0:
        if n % 2 == 1:
            result *= a
        a *= a
        n //= 2
    return result
