```python
import json

class FileWriteError(Exception):
    pass

class SettingsManager:
    __FILE_NAME = 'settings.json'

    def read_settings(self) -> dict:
        try:
            with open(self.__FILE_NAME, 'r') as file:
                settings = json.load(file)
                return settings
        except (FileNotFoundError, json.JSONDecodeError):
            return {}

    def update_settings(self, new_settings: dict) -> None:
        try:
            with open(self.__FILE_NAME, 'r') as file:
                settings = json.load(file)
            settings.update(new_settings)
            self.write_settings(settings)
        except (FileNotFoundError, json.JSONDecodeError):
            self.write_settings(new_settings)

    def write_settings(self, settings: dict) -> None:
        try:
            with open(self.__FILE_NAME, 'w') as file:
                json.dump(settings, file, indent=4)
        except (FileNotFoundError, IOError):
            raise FileWriteError("Error writing to settings file")

# Example usage
manager = SettingsManager()
print(manager.read_settings())  # Output: {}
manager.update_settings({'theme': 'dark', 'font_size': 12})
print(manager.read_settings())  # Output: {'theme': 'dark', 'font_size': 12}
