fn find_closest_led(x: f64, y: f64, led_data: &HashMap<&'static str, [f64; 2]>) -> &'static str {
    let mut closest_led = "";
    let mut min_distance = f64::MAX;

    for (led_name, coordinates) in led_data.iter() {
