func calculateMessageContainerOrigin(position: MessagePosition,
                                     itemWidth: CGFloat,
                                     avatarSize: CGSize,
                                     messageContainerSize: CGSize,
                                     messageContainerPadding: UIEdgeInsets,
                                     attachmentLayout: AttachmentLayout,
                                     durationSize: CGSize,
                                     durationPadding: UIEdgeInsets) -> CGPoint {
    var origin: CGPoint = .zero

    origin.y = messageContainerPadding.top

    switch position {
    case .leading:
        // For leading position, origin.x remains at its initial value (0)
        break
    case .trailing:
        // Calculate origin.x for trailing position
        origin.x = itemWidth - avatarSize.width - messageContainerPadding.right - messageContainerSize.width - attachmentLayout.width - durationSize.width - durationPadding.right - durationPadding.left
    }

    return origin
}
```

The `calculateMessageContainerOrigin` function takes the message position, item width, avatar size, message container size, padding, attachment layout, duration size, and duration padding as input parameters. It then calculates the origin point for the message container based on the given position and layout constraints and returns the resulting origin point.

