```rust
use std::time::Duration;

struct Packet {
    sent: Duration,
    received: Option<Duration>,
}

struct PacketManager {
    recv_packets: Vec<Packet>,
}

impl PacketManager {
    /// Calculate the average time that packets are taking to return over a period of time.
    pub fn mean_recv_time(&self, time_avg: Duration) -> Option<Duration> {
        if self.recv_packets.is_empty() {
            return None;
        }
        let filtered_packets: Vec<&Packet> = self.recv_packets
            .iter()
            .filter(|x| x.received.is_some() && (x.sent + x.received.unwrap()).elapsed() < time_avg)
            .collect();

        if filtered_packets.is_empty() {
            return None;
        }

        let total_time: Duration = filtered_packets.iter()
            .map(|packet| packet.received.unwrap() - packet.sent)
            .sum();

        Some(total_time / filtered_packets.len() as u32)
    }
}
```

In the solution, the `mean_recv_time` method is completed to handle the case when there are no received packets by returning `None`. It filters the received packets based on the time difference between their sent and received times and then calculates the average time for the filtered packets. If the filtered packets are empty, it returns `None`. Otherwise, it calculates the total time for the filtered packets and returns the average time.

