  getCurrentNodeType: () => NodeType;
  addChildToCurrentNode: () => void;
  hasChildren: () => boolean;
} {
  let currentNode: RootNode | TemplateChildNode | null = null;

  const setCurrentNode = (node: RootNode | TemplateChildNode | null): void => {
    currentNode = node;
  };

  const getCurrentNodeType = (): NodeType => {
    if (currentNode === null) {
      return "null";
    } else if (currentNode instanceof RootNode) {
      return "RootNode";
    } else {
      return "TemplateChildNode";
    }
  };

  const addChildToCurrentNode = (): void => {
    if (currentNode instanceof RootNode) {
      currentNode.addChild(new TemplateChildNode());
    }
  };

  const hasChildren = (): boolean => {
    if (currentNode instanceof RootNode) {
      return currentNode.children.length > 0;
    } else {
      return false;
    }
  };

  return {
    setCurrentNode,
    getCurrentNodeType,
    addChildToCurrentNode,
    hasChildren,
  };
}
```

In this solution, the `treeManager` function returns an object with methods to manage the tree nodes. The `setCurrentNode` method sets the current node, `getCurrentNodeType` returns the type of the current node, `addChildToCurrentNode` adds a child to the current node if it's a `RootNode`, and `hasChildren` checks if the current node has children. The implementation ensures that the operations are performed according to the specified requirements.

