```typescript
class EventDispatcher {
  private _listeners: { [key: string]: Function[] } = {};

  addEventListener(type: string, listener: Function): void {
    if (!this._listeners[type]) {
      this._listeners[type] = [];
    }
    this._listeners[type].push(listener);
  }

  dispatchEvent(type: string, data?: any): void {
    const listeners = this._listeners[type];
    if (listeners) {
      for (const listener of listeners) {
        listener(data);
      }
    }
  }

  removeEventListener(type: string, listener: Function): void {
    const listeners = this._listeners[type];
    if (listeners) {
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    }
  }
}
```

This solution provides a complete implementation of the `EventDispatcher` class with the `addEventListener`, `dispatchEvent`, and `removeEventListener` methods. The `addEventListener` method adds event listeners to the specified event type, the `dispatchEvent` method triggers the event and calls all the associated listeners, and the `removeEventListener` method removes a specific event listener for a given event type.

