enum CidrError {
    InvalidPrefixLength,
}

fn validate_subnet_mask(mask: u32) -> Result<usize, CidrError> {
    let length = (!mask).leading_zeros();
    if mask.leading_zeros() == 0 && mask.trailing_zeros() == mask.count_zeros() {
        Ok(length as usize)
    } else {
        Err(CidrError::InvalidPrefixLength)
    }
}

fn main() {
    // Test cases
    assert_eq!(validate_subnet_mask(4294967295), Ok(0)); // 11111111.11111111.11111111.11111111 (32 bits set to 1)
    assert_eq!(validate_subnet_mask(4294967294), Err(CidrError::InvalidPrefixLength)); // 11111111.11111111.11111111.11111110 (31 bits set to 1)
    assert_eq!(validate_subnet_mask(4294901760), Ok(20)); // 11111111.11111111.11110000.00000000 (20 bits set to 1)
}
```

