import java.util.Optional;
import java.util.jar.Manifest;
import java.util.jar.JarFile;
import java.io.IOException;
import java.net.URL;

public class ManifestExtractor {
    public static void main(String[] args) {
        // Prompt the user to input the path to a JAR file
        System.out.print("Enter the path to the JAR file: ");
        String jarFilePath = System.console().readLine();

        try {
            // Create a JarFile object using the specified JAR file path
            JarFile jarFile = new JarFile(jarFilePath);

            // Extract the manifest from the JarFile using ManifestUtils
            Optional<Manifest> manifestOptional = ManifestUtils.getManifest(jarFile.getClass());

            if (manifestOptional.isPresent()) {
                // Display the extracted manifest information to the user
                System.out.println("Manifest Information:");
                System.out.println("---------------------");
                Manifest manifest = manifestOptional.get();
                manifest.getMainAttributes().forEach((key, value) -> System.out.println(key + ": " + value));
            } else {
                System.out.println("The specified JAR file does not contain a manifest file.");
            }
        } catch (IOException e) {
            System.out.println("Error: The specified JAR file does not exist or cannot be opened.");
        }
    }
}
```

