trait Cache {
    fn get(&self, key: &str) -> Result<Option<Vec<u8>>>;
    fn put(&mut self, key: String, value: Vec<u8>) -> Result<()>;
    fn remove(&mut self, key: &str) -> Result<()>;
}

struct PlatformCache {
    #[cfg(unix)]
    dense_file_cache: DenseFileCache,
    #[cfg(not(unix))]
    hashmap_cache: HashMapCache,
}

impl Cache for PlatformCache {
    fn get(&self, key: &str) -> Result<Option<Vec<u8>>> {
