import UIKit

let imageCache = NSCache<NSString, UIImage>()

extension UIImageView {
    func loadImageFromURL(_ url: URL, placeholder: UIImage? = nil) {
        self.image = placeholder

        if let cachedImage = imageCache.object(forKey: url.absoluteString as NSString) {
            self.image = cachedImage
            return
        }

        URLSession.shared.dataTask(with: url) { (data, response, error) in
            if let error = error {
                print("Error loading image: \(error)")
                return
            }

            guard let data = data, let downloadedImage = UIImage(data: data) else {
                print("Invalid image data")
                return
            }

            imageCache.setObject(downloadedImage, forKey: url.absoluteString as NSString)

            DispatchQueue.main.async {
                self.image = downloadedImage
            }
        }.resume()
    }
}
```

In the solution, we first set the placeholder image on the image view. Then, we check if the image is already cached using the URL as the key. If the image is found in the cache, we set it on the image view and return early.

If the image is not cached, we use URLSession to asynchronously download the image from the provided URL. We handle potential errors and invalid image data, and if the download is successful, we cache the image and set it on the image view using the main queue.

