import java.util.HashMap;
import java.util.Map;

class Dropdown {
    private String name;

    public Dropdown(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

public class DropdownFactory {
    private static Map<Class<? extends Dropdown>, Dropdown> instanceMap = new HashMap<>();

    private DropdownFactory() {
        // Private constructor to prevent instantiation of the factory
    }

    public static <T extends Dropdown> T createDropdown(Class<T> clazz) throws IllegalAccessException, InstantiationException {
        if (instanceMap.containsKey(clazz)) {
            return clazz.cast(instanceMap.get(clazz));
        } else {
            T dropdownInstance = clazz.newInstance();
            instanceMap.put(clazz, dropdownInstance);
            return dropdownInstance;
        }
    }

    public static Map<Class<? extends Dropdown>, Dropdown> getDropdownInstances() {
        return new HashMap<>(instanceMap);
    }

    public static void main(String[] args) throws InstantiationException, IllegalAccessException {
        Dropdown dropdown1 = DropdownFactory.createDropdown(Dropdown.class);
        System.out.println("Dropdown 1 name: " + dropdown1.getName());

        Dropdown dropdown2 = DropdownFactory.createDropdown(Dropdown.class);
        System.out.println("Dropdown 2 name: " + dropdown2.getName());

        System.out.println("Dropdown instances: " + DropdownFactory.getDropdownInstances());
    }
}
```

In this solution, the DropdownFactory class uses a static map to store instances of Dropdown classes. The `createDropdown` method checks if an instance of the specified class type already exists in the map. If it does, it returns the existing instance; otherwise, it creates a new instance, adds it to the map, and returns it. The `getDropdownInstances` method returns a copy of the map containing the class type of Dropdown as the key and the corresponding instance as the value. The Dropdown class simply provides a method to get the name of the instance.

