import base64
import json

def apply_patch(base64_patch: str, original_json: dict) -> dict:
    patch_bytes = base64.b64decode(base64_patch)
    patch_str = patch_bytes.decode('utf-8')
    patch = json.loads(patch_str)

    apply_patch_recursive(original_json, patch)

    return original_json

def apply_patch_recursive(json_obj, patch):
    for key, value in patch.items():
        if isinstance(value, dict):
            if key in json_obj and isinstance(json_obj[key], dict):
                apply_patch_recursive(json_obj[key], value)
        else:
            json_obj[key] = value
```

