using System;

public class Stack
{
    private int[] elements;
    private int top;
    private int capacity;

    public Stack(int capacity)
    {
        this.capacity = capacity;
        this.elements = new int[capacity];
        this.top = -1;
    }

    public void Push(int element)
    {
        if (top == capacity - 1)
        {
            throw new InvalidOperationException("Stack overflow");
        }
        elements[++top] = element;
    }

    public int Pop()
    {
        if (top == -1)
        {
            throw new InvalidOperationException("Stack underflow");
        }
        return elements[top--];
    }

    public int Peek()
    {
        if (top == -1)
        {
            throw new InvalidOperationException("Stack is empty");
        }
        return elements[top];
    }

    public bool IsEmpty()
    {
        return top == -1;
    }

    public static void Main()
    {
        // Test cases to demonstrate the functionality of the Stack class
        Stack stack = new Stack(5);
        stack.Push(10);
        stack.Push(20);
        stack.Push(30);
        Console.WriteLine(stack.Pop()); // Output: 30
        Console.WriteLine(stack.Peek()); // Output: 20
        Console.WriteLine(stack.IsEmpty()); // Output: false
        Console.WriteLine(stack.Pop()); // Output: 20
        Console.WriteLine(stack.Pop()); // Output: 10
        Console.WriteLine(stack.IsEmpty()); // Output: true
    }
}
