import java.io.File;
import java.io.FilenameFilter;
import java.util.ArrayList;
import java.util.logging.Logger;

import com.sun.xacml.ParsingException;
import com.sun.xacml.finder.PolicyFinder;
import com.sun.xacml.support.finder.PolicyReader;

public class XacmlPolicyManager {
    public static void main(String[] args) {
        String directoryPath = "path_to_directory"; // Replace with the actual directory path

        File directory = new File(directoryPath);
        File[] policyFiles = directory.listFiles(new FilenameFilter() {
            @Override
            public boolean accept(File dir, String name) {
                return name.toLowerCase().endsWith(".xml");
            }
        });

        ArrayList<PolicyInfo> policies = new ArrayList<>();

        for (File policyFile : policyFiles) {
            try {
                PolicyReader policyReader = new PolicyReader(policyFile.getAbsolutePath());
                PolicyFinder policyFinder = new PolicyFinder();
                policyFinder.setPolicyReader(policyReader);
                policyFinder.init();

                String policyName = policyReader.getPolicy().getPolicyId().toString();
                int numRules = policyReader.getPolicy().getRules().size();

                policies.add(new PolicyInfo(policyName, numRules));
            } catch (ParsingException e) {
                Logger.getLogger(XacmlPolicyManager.class.getName()).severe("Parsing exception for file: " + policyFile.getName());
            }
        }

        // Further processing of the extracted policy information
        for (PolicyInfo policy : policies) {
            System.out.println("Policy Name: " + policy.getName() + ", Number of Rules: " + policy.getNumRules());
        }
    }

    static class PolicyInfo {
        private String name;
        private int numRules;

        public PolicyInfo(String name, int numRules) {
            this.name = name;
            this.numRules = numRules;
        }

        public String getName() {
            return name;
        }

        public int getNumRules() {
            return numRules;
        }
    }
}
```

