def generate_inward_payment_report(data):
    report = {
        'booking_reports': [],
        'payment_mode_reports': {},
        'received_from_reports': {}
    }

    for booking in data.get('bookings', []):
        total_actual_amount = 0
        total_tds = 0
        received_from = booking['pending_inward'].get('customer', None)
        if not received_from:
            received_from = booking['pending_inward'].get('customer_name', None)

        for inward_payment in data['inward_payments_data']:
            if booking['booking_id'] in inward_payment['booking_id']:
                total_actual_amount += inward_payment['actual_amount']
                total_tds += inward_payment['tds']

                if inward_payment['payment_mode'] in report['payment_mode_reports']:
                    report['payment_mode_reports'][inward_payment['payment_mode']] += inward_payment['actual_amount']
                else:
                    report['payment_mode_reports'][inward_payment['payment_mode']] = inward_payment['actual_amount']

                if received_from in report['received_from_reports']:
                    report['received_from_reports'][received_from] += inward_payment['actual_amount']
                else:
                    report['received_from_reports'][received_from] = inward_payment['actual_amount']

        report['booking_reports'].append({
            'booking_id': booking['booking_id'],
            'total_actual_amount': total_actual_amount,
            'total_tds': total_tds
        })

    return report
```

