    public class StringJsonSchema : JsonSchemaBase
    {
        public int? MinLength { get; set; }
        public int? MaxLength { get; set; }
        public string Pattern { get; set; }

        public override bool Validate(JToken json)
        {
            if (json.Type != JTokenType.String)
            {
                return false; // Not a string, validation fails
            }

            string jsonString = json.Value<string>();

            if (MinLength.HasValue && jsonString.Length < MinLength)
            {
                return false; // Length is less than the minimum required
            }

            if (MaxLength.HasValue && jsonString.Length > MaxLength)
            {
                return false; // Length is greater than the maximum allowed
            }

            if (!string.IsNullOrEmpty(Pattern) && !Regex.IsMatch(jsonString, Pattern))
            {
                return false; // String does not match the specified pattern
            }

            return true; // All validation checks passed, string is valid
        }
    }
}
