// Define the Fields enum to represent the different field types
enum Fields {
    At(Vec<String>),
    Star(Vec<String>),
    Split(Vec<String>),
}

// Implement the parser function to parse the input query and return the parsed fields
fn parse_query(query: &str) -> Fields {
    let parts: Vec<&str> = query.split(' ').collect();

    match parts.len() {
        1 => {
            if parts[0].is_empty() {
                Fields::At(Vec::new())  // Empty field
            } else {
                Fields::Star(vec![parts[0].to_owned()])  // Single field with delimiter
            }
        }
        _ => Fields::Split(parts.iter().map(|s| s.to_owned()).collect()),  // Multiple fields separated by a delimiter
    }
}

