            setup_keywords = setup_call.value.keywords
            for arg in setup_args:
                if isinstance(arg, ast.Str):
                    if arg.s:
                        metadata['name'] = arg.s
            for keyword in setup_keywords:
                if isinstance(keyword.value, ast.Str):
                    if keyword.arg == 'version':
                        metadata['version'] = keyword.value.s
                    elif keyword.arg == 'description':
                        metadata['description'] = keyword.value.s
                    elif keyword.arg == 'long_description':
                        with open(keyword.value.s, 'r', encoding='utf-8', errors='ignore') as long_desc_file:
                            metadata['long_description'] = long_desc_file.read()
                    elif keyword.arg == 'keywords':
                        metadata['keywords'] = keyword.value.s
    return metadata
```

