export function isCircularable(destPos: number, range: number[], circular: boolean[]): boolean {
  const [start, end] = range;
  const [allowPositive, allowNegative] = circular;

  if (destPos >= start && destPos <= end) {
    return true; // Destination position is within the range
  }

  if (allowPositive && allowNegative) {
    return true; // Circular movement allowed in both directions
  }

  if (allowPositive) {
    const distanceToPositiveEnd = end - destPos;
    const distanceToNegativeStart = destPos - start + end;
    return distanceToPositiveEnd <= distanceToNegativeStart;
  }

  if (allowNegative) {
    const distanceToNegativeStart = destPos - start;
    const distanceToPositiveEnd = start + end - destPos;
    return distanceToNegativeStart <= distanceToPositiveEnd;
  }

  return false; // Circular movement cannot reach the destination position
}

// Calculate the final position after considering circular movement
export function getCirculatedPos(pos: number, range: number[], circular: boolean[]): number {
  const [start, end] = range;
  const [allowPositive, allowNegative] = circular;

  if (pos >= start && pos <= end) {
    return pos; // Current position is within the range
  }

  if (allowPositive && allowNegative) {
    const distanceToPositiveEnd = end - pos;
    const distanceToNegativeStart = pos - start + end;
    return distanceToPositiveEnd <= distanceToNegativeStart ? end : start;
  }

  if (allowPositive) {
    return pos < start ? end : start;
  }

  if (allowNegative) {
    return pos > end ? start : end;
  }

  return pos; // No circular movement allowed
}
