public class CepValidator {
    public boolean validateCep(String cep) {
        // Check if the CEP consists of exactly 8 digits
        if (cep.length() != 8) {
            return false;
        }

        // Check if the first digit is not 0
        if (cep.charAt(0) == '0') {
            return false;
        }

        // Check if the CEP contains only digits
        for (char c : cep.toCharArray()) {
            if (!Character.isDigit(c)) {
                return false;
            }
        }

        return true;
    }
}
