```swift
class ReactiveAnimation {
    let duration: TimeInterval
    let animationClosure: (Double) -> Void

    init(duration: TimeInterval, animationClosure: @escaping (Double) -> Void) {
        self.duration = duration
        self.animationClosure = animationClosure
    }

    func play(completion: @escaping () -> Void) {
        let startTime = Date.timeIntervalSinceReferenceDate
        let endTime = startTime + duration

        let animationTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 60.0, repeats: true) { timer in
            let currentTime = Date.timeIntervalSinceReferenceDate
            let progress = min((currentTime - startTime) / self.duration, 1.0)
            self.animationClosure(progress)

            if currentTime >= endTime {
                timer.invalidate()
                completion()
            }
        }

        RunLoop.current.add(animationTimer, forMode: .common)
    }

    func then(_ animation: ReactiveAnimation) -> ReactiveAnimation {
        return ReactiveAnimation(duration: self.duration + animation.duration) { progress in
            if progress <= 1.0 {
                self.animationClosure(min(progress, 1.0))
            } else {
                animation.animationClosure(min(progress - 1.0, 1.0))
            }
        }
    }
}

func sequence(_ animations: [ReactiveAnimation]) -> ReactiveAnimation {
    guard let firstAnimation = animations.first else {
        fatalError("Empty animation sequence")
    }

    if animations.count == 1 {
        return firstAnimation
    }

    var combinedAnimation = firstAnimation
    for index in 1..<animations.count {
        combinedAnimation = combinedAnimation.then(animations[index])
    }

    return combinedAnimation
}
```

