import json
import xml.etree.ElementTree as ET

class InvalidJSONException(Exception):
    pass

def json_to_xml(json_obj):
    try:
        xml_root = ET.Element('root')
        _json_to_xml(json_obj, xml_root)
        return ET.tostring(xml_root, encoding='unicode')
    except (ValueError, TypeError) as e:
        raise InvalidJSONException(f"Invalid JSON: {e}")

def _json_to_xml(json_obj, parent):
    if isinstance(json_obj, dict):
        for key, value in json_obj.items():
            element = ET.SubElement(parent, key)
            _json_to_xml(value, element)
    elif isinstance(json_obj, list):
        for item in json_obj:
            _json_to_xml(item, parent)
    else:
        parent.text = str(json_obj)
```

