use std::str::FromStr;

fn total_days_in_interval(interval: &str) -> Option<u32> {
    let parts: Vec<&str> = interval.split_whitespace().collect();
    if parts.len() != 2 {
        return None;
    }

    let base_time = parts[0];
    let duration = parts[1];

    match (base_time, duration) {
        ("now", "1-d") => Some(1),
        ("now", "7-d") => Some(7),
        ("today", "1-m") => Some(30),
        _ => None,
    }
}

fn main() {
    assert_eq!(total_days_in_interval("now 1-d"), Some(1));
    assert_eq!(total_days_in_interval("today 1-m"), Some(30));
    assert_eq!(total_days_in_interval("now 7-d"), Some(7));
    assert_eq!(total_days_in_interval("invalid interval"), None);
}
```

