fn erlang_record_headers(header: &str) -> HashMap<String, String> {
    let header = header.trim_matches(|c| c == '{' || c == '}');
    let parts: Vec<&str> = header.split(',').map(|s| s.trim()).collect();

    if parts.len() < 2 {
        panic!("Invalid record header format");
    }

    let record_name = parts[0].trim();
    let field_values = &parts[1..];

    let field_names = vec!["name", "age"]; // Replace with actual field names from record definition

    if field_values.len() != field_names.len() {
        panic!("Number of field values does not match the record definition");
    }

    let mut result = HashMap::new();
    for (name, value) in field_names.iter().zip(field_values) {
        result.insert(name.to_string(), value.to_string());
    }

    result
}

fn main() {
    let header = "{person, john, 30}";
    let parsed_header = erlang_record_headers(header);
    println!("{:?}", parsed_header);
}
```

