def dfsTraversal(startNode, graph):
    visited = set()
    traversal_order = []

    def dfs(node):
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            for neighbor in graph[node]:
                dfs(neighbor)

    dfs(startNode)
    return traversal_order
```

