import time

def execution_time(func):
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        execution_seconds = end_time - start_time
        func.execution_time = execution_seconds
        print(f"Execution time of {func.__name__}: {execution_seconds} seconds")
        return result
    return wrapper

class MathOperations:
