using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Claims;

public class ClaimProcessor
{
    public ClaimsIdentity ProcessClaims(ClaimsIdentity identity)
    {
        var matchingClaims = identity.Claims.Where(x => x.Type == ClaimType.Auth0Roles).ToList();
        var claimsToAdd = new List<Claim>();

        for (var index = matchingClaims.Count - 1; index >= 0; index--)
        {
            var claim = matchingClaims[index];
            // Modify the claim as needed
            claim = new Claim(claim.Type, claim.Value + "_Modified", claim.ValueType, claim.Issuer, claim.OriginalIssuer, claim.Subject);
            // Add the modified claim to the list of claims to be added back
            claimsToAdd.Add(claim);
        }

        // Add the modified claims back to the user's identity
        foreach (var claim in claimsToAdd)
        {
            identity.AddClaim(claim);
        }

        return identity;
    }
}
