class Player {
    var currentRoom: Room
    var inventory: [String]

    init(startingRoom: Room) {
        self.currentRoom = startingRoom
        self.inventory = []
    }

    func move(to room: Room) -> String {
        guard let newRoom = currentRoom.exits[room.description] else {
            return "Cannot move to that room."
        }
        currentRoom = newRoom
        return currentRoom.description
    }

    func interact(with object: String) -> String {
        if currentRoom.objects.contains(object) {
            if object == "key" {
                inventory.append(object)
                currentRoom.objects.removeAll { $0 == object }
                return "You picked up the key."
            } else {
                return "You cannot interact with that object."
            }
        } else {
            return "The object does not exist in this room."
        }
    }
}

// Create the initial state of the game
func createGame() -> Room {
    let startingRoom = Room(description: "You are in a dimly lit hallway.",
                            exits: [:],
                            objects: ["key", "book"])
    let secondRoom = Room(description: "You are in a dusty library.",
                          exits: [:],
                          objects: ["candle", "note"])
    startingRoom.exits["library"] = secondRoom
    secondRoom.exits["hallway"] = startingRoom
    return startingRoom
}

