public class StunUdpClient
{
    public int Port { get; set; }
    public string Hostname { get; set; }

    public StunUdpClient(string hostname, int port = 3478)
    {
        this.Hostname = hostname;
        this.Port = port;
    }

    public bool Connect()
    {
        using (UdpClient client = new UdpClient())
        {
            IPEndPoint endPoint = new IPEndPoint(Dns.GetHostAddresses(Hostname)[0], Port);
            client.Connect(endPoint);

            byte[] sendBytes = new byte[1]; // Sending an empty packet
            client.Send(sendBytes, sendBytes.Length);

            try
            {
                client.Client.ReceiveTimeout = 3000; // Set a 3-second timeout for receiving a response
                client.Receive(ref endPoint); // Wait for a response

                // If a response is received, the connection is successful
                return true;
            }
            catch (SocketException)
            {
                // If no response is received within the timeout period, the connection is considered unsuccessful
                return false;
            }
        }
    }
}
```

