from typing import List

def validate_configuration(json_config: dict) -> List[str]:
    invalid_components = []
    for service in json_config.get("services", []):
        for component in service.get("components", []):
            component_name = component["StackServiceComponents"]["component_name"]
            hostnames = component["StackServiceComponents"]["hostnames"]
            if not hostnames or len(hostnames) != len(set(hostnames)):
                invalid_components.append(component_name)
    return invalid_components
