func processWebSocketMessage(_ message: Any) -> String {
    if let text = message as? String,
       let data = text.data(using: .utf8),
       let json = try? JSONSerialization.jsonObject(with: data, options: []) as? [String: Any],
       let operation = json["operation"] as? String,
       let operands = json["operands"] as? [Int] {

        switch operation {
        case "add":
            return "Result: \(operands.reduce(0, +))"
        case "subtract":
            guard operands.count == 2 else { return "Error: Invalid number of operands for subtraction" }
            return "Result: \(operands[0] - operands[1])"
        case "multiply":
            return "Result: \(operands.reduce(1, *))"
        case "divide":
            guard operands.count == 2 && operands[1] != 0 else { return "Error: Invalid operands for division" }
            return "Result: \(Double(operands[0]) / Double(operands[1]))"
        default:
