using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    static void Main()
    {
        string logFilePath = "path_to_log_file.log";
        List<Header> headers = ParseLog(logFilePath);
        foreach (var header in headers)
        {
            Console.WriteLine($"Task ID: {header.Id}, Started: {header.Started}");
        }
    }

    static List<Header> ParseLog(string logFilePath)
    {
        List<Header> headers = new List<Header>();
        string[] logLines = File.ReadAllLines(logFilePath);

        for (int i = 0; i < logLines.Length; i += 2)
        {
            if (logLines[i].StartsWith("Task started: ") && i + 1 < logLines.Length && logLines[i + 1].StartsWith("Task ID: "))
            {
                string timestamp = logLines[i].Substring("Task started: ".Length);
                string taskId = logLines[i + 1].Substring("Task ID: ".Length);

                if (DateTime.TryParse(timestamp, out DateTime started))
                {
                    headers.Add(new Header { Id = taskId, Started = started });
                }
                else
                {
                    Console.WriteLine($"Invalid timestamp format: {timestamp}");
                }
            }
            else
            {
                Console.WriteLine($"Invalid log entry format at line {i + 1}");
            }
        }

        return headers;
    }

    class Header
    {
        public string Id { get; set; }
        public DateTime Started { get; set; }
    }
}
