import numpy as np

class LinearInterpolator1d:
    def __init__(self, x, y, method='Constant', left=None, right=None):
        self.x = x
        self.y = y
        self.method = method
        self.left = left if left is not None else y[0]
        self.right = right if right is not None else y[-1]

    def __call__(self, x_new):
        if self.method == 'Constant':
            return self._interpolate_constant(x_new)
        elif self.method == 'Linear':
            return self._interpolate_linear(x_new)
        elif self.method == 'Quadratic':
            return self._interpolate_quadratic(x_new)
        else:
            raise ValueError("Invalid interpolation method")

    def _interpolate_constant(self, x_new):
        result = np.empty_like(x_new)
        result[x_new < self.x[0]] = self.left
