```java
import java.io.InputStream;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.Date;

public class SQLStatementHandler {
    public static void setParameter(PreparedStatement statement, int index, Object value) throws SQLException {
        Class<?> objClass = value.getClass();
        if (objClass.isArray()) {
            Class<?> componentType = value.getClass().getComponentType();
            if (componentType != null && componentType.isPrimitive()) {
                if (byte.class.isAssignableFrom(componentType)) {
                    statement.setBytes(index, (byte[]) value);
                }
            }
        } else if (objClass == Integer.class) {
            statement.setInt(index, (Integer) value);
        } else if (objClass == String.class) {
            statement.setString(index, (String) value);
        } else if (objClass == Boolean.class) {
            statement.setBoolean(index, (Boolean) value);
        } else if (objClass == Double.class) {
            statement.setDouble(index, (Double) value);
        } else if (objClass == Float.class) {
            statement.setFloat(index, (Float) value);
        } else if (value instanceof InputStream) {
            statement.setBlob(index, (InputStream) value);
        } else if (objClass == Date.class) {
            long time = ((Date) value).getTime();
            statement.setDate(index, new java.sql.Date(time));
        } else {
            throw new SQLException("Unsupported parameter type: " + objClass.getName());
        }
    }
}
```

The `setParameter` method uses reflection to determine the type of the `value` and sets it to the corresponding parameter type in the SQL statement using the appropriate `set` method. If the type is not supported, it throws a `SQLException` indicating the unsupported parameter type.

