```swift
class LRUCache {
    class Node {
        let key: Int
        var value: Int
        var prev: Node?
        var next: Node?

        init(_ key: Int, _ value: Int) {
            self.key = key
            self.value = value
        }
    }

    var capacity: Int
    var cache: [Int: Node]
    var head: Node
    var tail: Node

    init(_ capacity: Int) {
        self.capacity = capacity
        self.cache = [:]
        self.head = Node(-1, -1)
        self.tail = Node(-1, -1)
        self.head.next = self.tail
        self.tail.prev = self.head
    }

    func removeNode(_ node: Node) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
    }

    func addToHead(_ node: Node) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    func get(_ key: Int) -> Int {
        if let node = cache[key] {
            removeNode(node)
            addToHead(node)
            return node.value
        }
        return -1
    }

    func put(_ key: Int, _ value: Int) {
        if let node = cache[key] {
            node.value = value
            removeNode(node)
            addToHead(node)
        } else {
            let newNode = Node(key, value)
            cache[key] = newNode
            addToHead(newNode)
            if cache.count > capacity {
                if let tailPrev = tail.prev {
                    removeNode(tailPrev)
                    cache[tailPrev.key] = nil
                }
            }
        }
    }
}
```

The `LRUCache` class uses a doubly linked list and a dictionary to efficiently support the put and get operations. The `Node` class represents each key-value pair in the cache, and the `LRUCache` class maintains a doubly linked list to keep track of the most recently used items. The `get` method retrieves the value associated with the key and updates the position of the node in the linked list. The `put` method inserts or updates the value associated with the key, evicts the least recently used item if the cache is full, and updates the position of the node in the linked list.

