import re

def parse_migration_file(file_path: str) -> dict:
    with open(file_path, 'r') as file:
        content = file.read()
        match = re.search(r'# Generated by Django (\d+\.\d+\.\d+) on (\d{4}-\d{2}-\d{2})', content)
