def generate_sql_script(operations):
    sql_script = ""
    for operation in operations:
        if isinstance(operation, migration.AddField):
            field_definition = operation.field
            sql_script += f"CREATE TABLE {operation.model_name} ({operation.name} {field_definition.__class__.__name__.upper()}({field_definition.max_length}) DEFAULT {field_definition.default});\n"
        elif isinstance(operation, migration.AlterField):
            field_definition = operation.field
            sql_script += f"ALTER TABLE {operation.model_name} ALTER COLUMN {operation.name} SET DEFAULT {field_definition.default};\n"
        elif isinstance(operation, migration.RemoveField):
            sql_script += f"ALTER TABLE {operation.model_name} DROP COLUMN {operation.name};\n"
    return sql_script
