```java
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class JavaConstructCounter {
    public static Map<String, Integer> countJavaConstructs(String sourceCode) {
        Map<String, Integer> constructCounts = new HashMap<>();
        int importCount = countOccurrences(sourceCode, "import ");
        int annotationCount = countOccurrences(sourceCode, "@");
        int publicCount = countOccurrences(sourceCode, "public ");
        int privateCount = countOccurrences(sourceCode, "private ");
        int protectedCount = countOccurrences(sourceCode, "protected ");

        constructCounts.put("importStatements", importCount);
        constructCounts.put("annotations", annotationCount);
        constructCounts.put("accessModifiers", publicCount + privateCount + protectedCount);

        Map<String, Integer> accessModifierCounts = new HashMap<>();
        accessModifierCounts.put("public", publicCount);
        accessModifierCounts.put("private", privateCount);
        accessModifierCounts.put("protected", protectedCount);
        constructCounts.put("accessModifiers", accessModifierCounts);

        return constructCounts;
    }

    private static int countOccurrences(String source, String pattern) {
        Pattern p = Pattern.compile(pattern);
        Matcher m = p.matcher(source);
        int count = 0;
        while (m.find()) {
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        String sourceCode = "import it.polimi.modaclouds.cpimlibrary.entitymng.statements.builders.lexer.TokenType;\n" +
                "import it.polimi.modaclouds.cpimlibrary.entitymng.statements.utils.CompareOperator;\n" +
                "import lombok.extern.slf4j.Slf4j;\n" +
                "\n" +
                "import javax.persistence.CascadeType;\n" +
                "import javax.persistence.JoinTable;\n" +
                "import javax.persistence.Query;\n" +
                "import java.lang.reflect.Field;\n" +
                "import java.util.Arrays;\n" +
                "import java.util.Iterator;\n" +
                "import java.util.List;\n" +
                "\n" +
                "public class ExampleClass {\n" +
                "    @Deprecated\n" +
                "    @Override\n" +
                "    protected void someMethod() {\n" +
                "        // Method implementation\n" +
                "    }\n" +
                "}";
        Map<String, Integer> counts = countJavaConstructs(sourceCode);
        System.out.println(counts);
    }
}
