function parseAnnotation(string $annotation): array {
    $annotation = str_replace(['@', '(', ')'], '', $annotation); // Remove @, (, and ) from the annotation string
    $pairs = explode(',', $annotation); // Split the annotation into key-value pairs

    $result = [];
    foreach ($pairs as $pair) {
        list($key, $value) = array_map('trim', explode('=', $pair)); // Split each pair into key and value
        if (strpos($value, '@') !== false) {
            $result[$key] = parseAnnotation($value); // If the value is another annotation, recursively parse it
        } else {
            $result[$key] = trim($value, '" '); // Store the key-value pair in the result map
        }
    }

    return $result;
}

