enum StackOperation<T> {
    case push(T)
    case pop
    case peek
    case resetStack
    case none
}

protocol CoordinatorRule {
    associatedtype Element
    func coordinate(_ operation: StackOperation<Element>, on stack: inout [Element])
}

struct Stack<Element>: CoordinatorRule {
    private var elements: [Element] = []

    mutating func coordinate(_ operation: StackOperation<Element>, on stack: inout [Element]) {
        switch operation {
        case .push(let element):
            elements.append(element)
        case .pop:
            if !elements.isEmpty {
                _ = elements.popLast()
            }
        case .peek:
            if let topElement = elements.last {
                print("Top element: \(topElement)")
            } else {
                print("Stack is empty")
            }
        case .resetStack:
            elements.removeAll()
        case .none:
            break
        }
    }
}

// Example usage
var stack = Stack<Int>()
stack.coordinate(.push(5), on: &stack.elements) // Push 5 to the stack
stack.coordinate(.push(10), on: &stack.elements) // Push 10 to the stack
stack.coordinate(.peek, on: &stack.elements) // Peek the top element
stack.coordinate(.pop, on: &stack.elements) // Pop the top element
stack.coordinate(.resetStack, on: &stack.elements) // Reset the stack
```

