class ShoppingCart {
    private $cart;

    public function __construct() {
        $this->cart = [];
    }

    public function addItem($item, $quantity, $price) {
        if (isset($this->cart[$item])) {
            $this->cart[$item]['quantity'] += $quantity;
        } else {
            $this->cart[$item] = ['quantity' => $quantity, 'price' => $price];
        }
    }

    public function removeItem($item) {
        unset($this->cart[$item]);
    }

    public function calculateTotal() {
        $total = 0;
        foreach ($this->cart as $item) {
            $total += $item['quantity'] * $item['price'];
        }
        return $total;
    }

    public function applyDiscount($code, $percentage) {
        // Assume $code is a string representing the discount code
        // Check if the provided code matches the given code
        if ($code === 'DISCOUNT123') {
            $total = $this->calculateTotal();
            $discountedTotal = $total - ($total * $percentage / 100);
            return $discountedTotal;
        } else {
            return $this->calculateTotal();
        }
    }
}

// Example usage
