use std::borrow::Borrow;
use std::rc::Rc;

pub struct RCow<'a, T: ?Sized> {
    data: CowData<'a, T>,
}

enum CowData<'a, T: ?Sized> {
    Borrowed(&'a T),
    Owned(Rc<T>),
}

impl<'a, T: ?Sized> RCow<'a, T> {
    pub fn from(data: T) -> Self {
        RCow {
            data: CowData::Owned(Rc::new(data)),
        }
    }

    pub fn borrow(&self) -> &T {
        match &self.data {
            CowData::Borrowed(b) => b,
            CowData::Owned(o) => o.borrow(),
        }
    }

    // Your task is to implement the `to_mut` method which returns a mutable reference to the data if it is not shared.
    pub fn to_mut(&mut self) -> &mut T {
        unimplemented!()
    }
}
```

