impl<'a, T: ?Sized> RCow<'a, T> {
    pub fn to_mut(&mut self) -> &mut T {
        match &mut self.data {
            CowData::Borrowed(_) => {
                let new_data = self.data.clone();
                self.data = new_data;
                self.to_mut()
            }
            CowData::Owned(o) => Rc::make_mut(o),
        }
    }
}
```

