import threading

class Frame:
    def __init__(self, item):
        self.item = item

class ThreadSafeStack:
    def __init__(self):
        self.frame = None
        self.lock = threading.Lock()

    def empty(self):
        with self.lock:
            return self.frame is None

    def push(self, item):
        with self.lock:
            new_frame = Frame(item)
            new_frame.next = self.frame
            self.frame = new_frame

    def pop(self):
        with self.lock:
            if self.frame is None:
                return None
            frame = self.frame
            self.frame = frame.next
        return frame.item
