fn count_pairs_with_difference(arr: &[i32], difference: i32) -> i32 {
    use std::collections::HashSet;

    let mut set = HashSet::new();
    let mut count = 0;

    for &num in arr {
        if set.contains(&(num - difference)) {
            count += 1;
        }
        if set.contains(&(num + difference)) {
            count += 1;
        }
        set.insert(num);
    }

    count
}
