    def __init__(self, name: str, initial_balance: float):
        self.name = name
        self.balance = initial_balance

class BankingSystem:
    def __init__(self):
        self.accounts: Dict[int, Account] = {}
        self.account_number = 1

    def create_account(self, name: str, initial_balance: float) -> int:
        acc_num = self.account_number
        self.accounts[acc_num] = Account(name, initial_balance)
        self.account_number += 1
        return acc_num

    def deposit(self, account_number: int, amount: float) -> float:
        if account_number in self.accounts:
            self.accounts[account_number].balance += amount
            return self.accounts[account_number].balance
        return 0

    def withdraw(self, account_number: int, amount: float) -> Union[float, str]:
        if account_number in self.accounts:
            if self.accounts[account_number].balance >= amount:
                self.accounts[account_number].balance -= amount
                return self.accounts[account_number].balance
            return "Insufficient funds"
        return "Invalid account number"

    def check_balance(self, account_number: int) -> Union[float, str]:
        if account_number in self.accounts:
            return self.accounts[account_number].balance
        return "Invalid account number"

# Test the BankingSystem
bank = BankingSystem()
acc_num1 = bank.create_account("Alice", 1000.0)
acc_num2 = bank.create_account("Bob", 500.0)

print(bank.deposit(acc_num1, 500.0))  # Output: 1500.0
print(bank.withdraw(acc_num2, 600.0))  # Output: "Insufficient funds"
print(bank.check_balance(acc_num1))  # Output: 1500.0
print(bank.check_balance(3))  # Output: "Invalid account number"
```

