```swift
enum DocumentationFragment {
    case data
    case js
    case themeSettings
}

class PackageController {
    static func awsDocumentationURL(owner: String, repository: String, reference: String, fragment: DocumentationFragment, path: String) throws -> URL {
        let baseURL = "http://spi-prod-docs.s3-website.us-east-2.amazonaws.com"
        let formattedOwner = owner.lowercased()
        let formattedRepository = repository.lowercased()
        let formattedReference = reference.lowercased()
        let fragmentPath: String

        switch fragment {
        case .data:
            fragmentPath = "data"
        case .js:
            fragmentPath = "js"
        case .themeSettings:
            fragmentPath = "theme-settings.json"
        }

        let constructedURL = "\(baseURL)/\(formattedOwner)/\(formattedRepository)/\(formattedReference)/\(fragmentPath)/\(path)"
        guard let url = URL(string: constructedURL) else {
            throw URLError(.badURL)
        }
        return url
    }
